 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, color, texture, mix, smoothstep, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new Group();
  const planeW = 2.56;
  const planeH = 1.6;

  const geometry = new PlaneGeometry(planeW, planeH);
  const material = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: true });

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      tex.anisotropy = 16;

      const u = uv();

      const mapColor = texture(tex).rgb;

      const surface = color(colors.surface);
      const ink = color(colors.ink);
      const gradientT = smoothstep(0.0, 1.0, u.y);
      const baseGrad = mix(surface, ink, gradientT);

      const noise = fract(
        sin(dot(u, vec2(12.9898, 78.233))).mul(43758.5453)
      ).mul(0.035);

      const shaded = mix(baseGrad, mapColor, 0.65).add(vec3(noise));

      material.colorNode = shaded;
      material.needsUpdate = true;
    });
  }

  const plane = new Mesh(geometry, material);
  group.add(plane);

  const accentBar = new Mesh(
    new PlaneGeometry(planeW * 0.18, 0.05),
    new MeshBasicNodeMaterial({ colorNode: color(colors.accent), transparent: true })
  );
  accentBar.position.set(0, -planeH * 0.36, 0.015);
  group.add(accentBar);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item?.text) continue;
    const text = String(item.text);
    const fontSize = item.typography?.fontSize ?? 42;
    const textObj = ctx.fontAtlas.createText(text, {
      fontSize,
      color: colors.ink,
      align: 'center'
    });
    textObj.position.z = 0.02;
    group.add(textObj);
  }

  const localTimelines = [];

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    localTimelines.forEach((tl) => tl?.kill());
    geometry.dispose();
    material.dispose();
    accentBar.geometry.dispose();
    accentBar.material.dispose();
    if (loadedTexture && loadedTexture.isTexture) loadedTexture.dispose();
  };

  return group;
}
